# ==============================================================================# 063_MODULE_DEPENDENCY_ENGINE.py (VERSÃO 2)# IOTEC MISSION CONTROL# ==============================================================================from pathlib import Pathimport sqlite3import astimport reDB = "mission_control.db"class ModuleDependencyEngine:    def __init__(self):        self.conn = sqlite3.connect(DB, timeout=30)        self.conn.row_factory = sqlite3.Row        self.conn.execute("PRAGMA journal_mode=WAL")        self.conn.execute("PRAGMA busy_timeout=30000")        self.cur = self.conn.cursor()        self.create_tables()    # -----------------------------------------------------------------    def create_tables(self):        self.cur.execute("""        CREATE TABLE IF NOT EXISTS module_dependencies(            id INTEGER PRIMARY KEY AUTOINCREMENT,            module_name TEXT,            dependency TEXT,            dependency_type TEXT        )        """)        self.cur.execute("""        CREATE TABLE IF NOT EXISTS dependency_errors(            id INTEGER PRIMARY KEY AUTOINCREMENT,            module_name TEXT,            error TEXT        )        """)        self.conn.commit()    # -----------------------------------------------------------------    def clear(self):        self.cur.execute("DELETE FROM module_dependencies")        self.cur.execute("DELETE FROM dependency_errors")        self.conn.commit()    # -----------------------------------------------------------------    def parse_ast(self, text):        deps = []        tree = ast.parse(text)        for node in ast.walk(tree):            if isinstance(node, ast.Import):                for alias in node.names:                    deps.append((alias.name, "import"))            elif isinstance(node, ast.ImportFrom):                if node.module:                    deps.append((node.module, "from"))        return deps    # -----------------------------------------------------------------    def parse_regex(self, text):        deps = []        pattern_import = re.compile(r"^\s*import\s+(.+)$")        pattern_from = re.compile(r"^\s*from\s+([^\s]+)\s+import")        for line in text.splitlines():            line = line.strip()            if not line or line.startswith("#"):                continue            m = pattern_import.match(line)            if m:                for item in m.group(1).split(","):                    dep = item.strip().split()[0]                    deps.append((dep, "import"))                continue            m = pattern_from.match(line)            if m:                deps.append((m.group(1), "from"))        return deps    # -----------------------------------------------------------------    def analyze(self, file):        path = Path(file)        try:            text = path.read_text(                encoding="utf-8",                errors="ignore"            )        except Exception as e:            self.cur.execute("""                INSERT INTO dependency_errors(                    module_name,error                )                VALUES(?,?)            """, (path.name, str(e)))            return []        try:            return self.parse_ast(text)        except Exception as e:            self.cur.execute("""                INSERT INTO dependency_errors(                    module_name,error                )                VALUES(?,?)            """, (path.name, str(e)))            return self.parse_regex(text)    # -----------------------------------------------------------------    def scan(self, folder="."):        self.clear()        files = 0        relations = 0        for py in Path(folder).rglob("*.py"):            deps = self.analyze(py)            files += 1            for dep, typ in deps:                self.cur.execute("""                INSERT INTO module_dependencies(                    module_name,                    dependency,                    dependency_type                )                VALUES(?,?,?)                """, (                    py.name,                    dep,                    typ                ))                relations += 1        self.conn.commit()        return files, relations    # -----------------------------------------------------------------    def stats(self):        dep = self.cur.execute(            "SELECT COUNT(*) FROM module_dependencies"        ).fetchone()[0]        err = self.cur.execute(            "SELECT COUNT(*) FROM dependency_errors"        ).fetchone()[0]        return dep, err# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    engine = ModuleDependencyEngine()    files, relations = engine.scan()    dep, err = engine.stats()    print("=" * 70)    print("DEPENDENCY ENGINE V2")    print("=" * 70)    print("Arquivos analisados :", files)    print("Dependências        :", dep)    print("Erros de sintaxe    :", err)    print("=" * 70)